from openpyxl import load_workbook

wb = load_workbook('/root/gdp.xlsx')
task = wb['Task']

print("=== Rows 34-50 in Task sheet ===")
for row in range(34, 51):
    print(f"\nRow {row}:")
    for col in range(1, 13):
        cell = task.cell(row=row, column=col)
        if cell.value is not None:
            try:
                fg = cell.fill.fgColor
                fill_info = f"fill_rgb={fg.rgb if fg.type=='rgb' else 'theme:'+str(fg.theme)}"
            except:
                fill_info = "fill=N/A"
            print(f"  {cell.coordinate}: {cell.value} ({fill_info})")
        else:
            # Check for yellow/blue fill even if no value
            try:
                fg = cell.fill.fgColor
                if fg.type == 'rgb' and fg.rgb == 'FFFFFF00':
                    print(f"  {cell.coordinate}: [empty yellow cell]")
                elif fg.type != 'rgb' or fg.rgb != '00000000':
                    print(f"  {cell.coordinate}: [empty, fill={fg.rgb if fg.type=='rgb' else 'theme:'+str(fg.theme)}]")
            except:
                pass
EOF
